// Two users: two equal figures 160 apart on the Z axis, generated by a 180° turn about the vertical axis.
// The nearer user (front left) carries the Iris head; the other stands back right.
import { user, checkUsers } from './one-user.mjs';
export const title = 'Two users';
export const reference = 'input';

export const spacing = 160; // Shoulder diameter 140 + 20 clearance.

export default function (api) {
  const { scene, around, mul, Y, Z } = api;
  const s = scene();
  s.hiddenLines = 'omit';
  [0, 1].map(k => around(mul(Z, spacing / 2), Y, k * Math.PI)).forEach((base, k) => user(s, api, base, k === 0));
  return s;
}

export function verify(s, api, assert) {
  checkUsers(s, api, assert, 2);
  const [a, b] = s.contours.filter(c => c.half).map(c => c.center);
  assert(Math.hypot(a[0] + b[0], a[1] + b[1], a[2] + b[2]) < 1e-9, 'Pair is point-symmetric about the vertical axis');
  assert(Math.abs(Math.hypot(...api.sub(a, b)) - spacing) < 1e-9);
}
